using System;
using System.Data;
using System.Drawing;
using System.IO;
using System.Windows.Forms;
using DevExpress.XtraPrinting;
using DevExpress.XtraReports.UI;

namespace StudentManager.Learning
{
    /// <summary>
    /// Báo cáo tổng kết lái xe (tạo layout động, lưu .repx để dùng với Report Designer).
    /// </summary>
    public class rptTongKetLaiXe
    {
        public const string REPORT_RELATIVE_PATH = "Report/StudentManager/Learning/Leaning_TongKetLaiXe.repx";

        public static string GetReportFullPath()
        {
            return Path.Combine(Application.StartupPath, REPORT_RELATIVE_PATH.Replace('/', Path.DirectorySeparatorChar));
        }

        public static XtraReport Create(
            DataTable dtbDetail,
            string[] arrSubjectHeaders,
            bool bolHasDrivingGroup,
            int intDrivingGroupStart,
            string[] arrDrivingSubHeaders,
            string strClassName,
            string strCourseName)
        {
            if (arrSubjectHeaders == null)
                arrSubjectHeaders = new string[0];
            if (arrDrivingSubHeaders == null)
                arrDrivingSubHeaders = new string[0];

            XtraReport report = new XtraReport();
            report.PaperKind = System.Drawing.Printing.PaperKind.A4;
            report.Landscape = true;
            report.Margins = new System.Drawing.Printing.Margins(40, 40, 40, 40);
            report.DataSource = dtbDetail;

            float fltPageWidth = report.PageWidth - report.Margins.Left - report.Margins.Right;

            DetailBand detailBand = new DetailBand();
            detailBand.HeightF = 22f;
            report.Bands.Add(detailBand);

            PageHeaderBand pageHeader = new PageHeaderBand();
            pageHeader.HeightF = 130f;
            report.Bands.Add(pageHeader);

            BuildDocHeader(pageHeader, fltPageWidth, strClassName, strCourseName);

            int intMarkCount = arrSubjectHeaders.Length;
            int intColCount = 3 + intMarkCount + 3; // STT, Ten, NgaySinh, Marks..., KetQua, KhoaHoc, GhiChu
            float[] arrWidths = BuildColumnWidths(fltPageWidth, intMarkCount);

            float fltTableTop = 95f;
            XRTable tblHeader = BuildHeaderTable(
                arrWidths,
                arrSubjectHeaders,
                bolHasDrivingGroup,
                intDrivingGroupStart,
                arrDrivingSubHeaders);
            tblHeader.LocationF = new PointF(0f, fltTableTop);
            tblHeader.WidthF = fltPageWidth;
            pageHeader.Controls.Add(tblHeader);
            pageHeader.HeightF = fltTableTop + tblHeader.HeightF + 2f;

            XRTable tblDetail = BuildDetailTable(arrWidths, intMarkCount);
            tblDetail.LocationF = new PointF(0f, 0f);
            tblDetail.WidthF = fltPageWidth;
            detailBand.Controls.Add(tblDetail);
            detailBand.HeightF = tblDetail.HeightF;

            return report;
        }

        public static void SaveReport(XtraReport report)
        {
            if (report == null)
                return;

            string strFullPath = GetReportFullPath();
            string strDir = Path.GetDirectoryName(strFullPath);
            if (!Directory.Exists(strDir))
                Directory.CreateDirectory(strDir);

            report.SaveLayout(strFullPath);
        }

        public static void ShowPreview(XtraReport report)
        {
            ReportPrintTool tool = new ReportPrintTool(report);
            tool.ShowPreview();
        }

        private static void BuildDocHeader(PageHeaderBand pageHeader, float fltPageWidth, string strClassName, string strCourseName)
        {
            float fltHalf = fltPageWidth / 2f;

            XRLabel lblLeft = new XRLabel();
            lblLeft.LocationF = new PointF(0f, 0f);
            lblLeft.SizeF = new SizeF(fltHalf, 45f);
            lblLeft.TextAlignment = TextAlignment.TopCenter;
            lblLeft.Font = new Font("Times New Roman", 11f, FontStyle.Bold);
            lblLeft.Multiline = true;
            lblLeft.Text = "BINH ĐOÀN 15\r\nTRƯỜNG CAO ĐẲNG NGHỀ SỐ 21";
            pageHeader.Controls.Add(lblLeft);

            XRLabel lblRight = new XRLabel();
            lblRight.LocationF = new PointF(fltHalf, 0f);
            lblRight.SizeF = new SizeF(fltHalf, 45f);
            lblRight.TextAlignment = TextAlignment.TopCenter;
            lblRight.Font = new Font("Times New Roman", 11f, FontStyle.Bold);
            lblRight.Multiline = true;
            lblRight.Text = "CỘNG HOÀ XÃ HỘI CHỦ NGHĨA VIỆT NAM\r\nĐộc lập - Tự ký - Hạnh phúc";
            pageHeader.Controls.Add(lblRight);

            // Sửa typo: Tự do
            lblRight.Text = "CỘNG HOÀ XÃ HỘI CHỦ NGHĨA VIỆT NAM\r\nĐộc lập - Tự do - Hạnh phúc";

            XRLine lineLeft = new XRLine();
            lineLeft.LocationF = new PointF((fltHalf - 160f) / 2f, 48f);
            lineLeft.SizeF = new SizeF(160f, 2f);
            lineLeft.LineWidth = 1;
            pageHeader.Controls.Add(lineLeft);

            XRLine lineRight = new XRLine();
            lineRight.LocationF = new PointF(fltHalf + (fltHalf - 140f) / 2f, 48f);
            lineRight.SizeF = new SizeF(140f, 2f);
            lineRight.LineWidth = 1;
            pageHeader.Controls.Add(lineRight);

            XRLabel lblTitle = new XRLabel();
            lblTitle.LocationF = new PointF(0f, 55f);
            lblTitle.SizeF = new SizeF(fltPageWidth, 20f);
            lblTitle.TextAlignment = TextAlignment.MiddleCenter;
            lblTitle.Font = new Font("Times New Roman", 12f, FontStyle.Bold);
            lblTitle.Text = "TỔNG HỢP KẾT QUẢ KỲ KIỂM TRA KẾT THÚC MÔN HỌC";
            pageHeader.Controls.Add(lblTitle);

            XRLabel lblSub = new XRLabel();
            lblSub.LocationF = new PointF(0f, 75f);
            lblSub.SizeF = new SizeF(fltPageWidth, 18f);
            lblSub.TextAlignment = TextAlignment.MiddleCenter;
            lblSub.Font = new Font("Times New Roman", 11f, FontStyle.Bold);
            lblSub.Text = String.Format("LỚP {0}, KHÓA {1}",
                strClassName == null ? "" : strClassName,
                strCourseName == null ? "" : strCourseName);
            pageHeader.Controls.Add(lblSub);
        }

        private static float[] BuildColumnWidths(float fltPageWidth, int intMarkCount)
        {
            int intColCount = 3 + intMarkCount + 3;
            float[] arr = new float[intColCount];

            arr[0] = 35f;   // STT
            arr[1] = 140f;  // Họ tên
            arr[2] = 70f;   // Ngày sinh

            float fltFixed = arr[0] + arr[1] + arr[2] + 70f + 70f + 90f; // + KetQua, KhoaHoc, GhiChu
            float fltRemain = fltPageWidth - fltFixed;
            if (fltRemain < 30f * intMarkCount)
                fltRemain = 30f * intMarkCount;

            float fltMarkW = intMarkCount > 0 ? (fltRemain / intMarkCount) : 0f;
            for (int i = 0; i < intMarkCount; i++)
                arr[3 + i] = fltMarkW;

            arr[3 + intMarkCount] = 70f;      // Kết quả
            arr[3 + intMarkCount + 1] = 70f;  // Khóa học
            arr[3 + intMarkCount + 2] = 90f;  // Ghi chú

            // chuẩn hoá tổng = page width
            float fltSum = 0f;
            for (int i = 0; i < arr.Length; i++)
                fltSum += arr[i];
            if (fltSum > 0f && Math.Abs(fltSum - fltPageWidth) > 0.5f)
            {
                float fltScale = fltPageWidth / fltSum;
                for (int i = 0; i < arr.Length; i++)
                    arr[i] = arr[i] * fltScale;
            }

            return arr;
        }

        private static XRTable BuildHeaderTable(
            float[] arrWidths,
            string[] arrSubjectHeaders,
            bool bolHasDrivingGroup,
            int intDrivingGroupStart,
            string[] arrDrivingSubHeaders)
        {
            XRTable table = new XRTable();
            table.BeginInit();
            table.Font = new Font("Times New Roman", 9f, FontStyle.Bold);
            table.Borders = BorderSide.All;
            table.TextAlignment = TextAlignment.MiddleCenter;

            int intMarkCount = arrSubjectHeaders.Length;

            if (!bolHasDrivingGroup || intDrivingGroupStart < 0 || arrDrivingSubHeaders.Length == 0)
            {
                XRTableRow row = new XRTableRow();
                row.HeightF = 36f;
                AddHeaderCell(row, "STT", arrWidths[0]);
                AddHeaderCell(row, "Họ và tên học sinh", arrWidths[1]);
                AddHeaderCell(row, "Ngày sinh", arrWidths[2]);
                for (int i = 0; i < intMarkCount; i++)
                    AddHeaderCell(row, arrSubjectHeaders[i], arrWidths[3 + i]);
                AddHeaderCell(row, "Kết quả", arrWidths[3 + intMarkCount]);
                AddHeaderCell(row, "Khóa học", arrWidths[3 + intMarkCount + 1]);
                AddHeaderCell(row, "Ghi chú", arrWidths[3 + intMarkCount + 2]);
                table.Rows.Add(row);
            }
            else
            {
                XRTableRow row1 = new XRTableRow();
                row1.HeightF = 22f;
                XRTableRow row2 = new XRTableRow();
                row2.HeightF = 22f;

                AddHeaderCell(row1, "STT", arrWidths[0], 2);
                AddHeaderCell(row1, "Họ và tên học sinh", arrWidths[1], 2);
                AddHeaderCell(row1, "Ngày sinh", arrWidths[2], 2);

                for (int i = 0; i < intMarkCount; i++)
                {
                    if (i == intDrivingGroupStart)
                    {
                        float fltGroupW = 0f;
                        for (int k = 0; k < arrDrivingSubHeaders.Length; k++)
                            fltGroupW += arrWidths[3 + i + k];
                        AddHeaderCell(row1, "TH lái xe", fltGroupW, 1, arrDrivingSubHeaders.Length);

                        for (int k = 0; k < arrDrivingSubHeaders.Length; k++)
                            AddHeaderCell(row2, arrDrivingSubHeaders[k], arrWidths[3 + i + k]);

                        i += arrDrivingSubHeaders.Length - 1;
                        continue;
                    }

                    AddHeaderCell(row1, arrSubjectHeaders[i], arrWidths[3 + i], 2);
                }

                AddHeaderCell(row1, "Kết quả", arrWidths[3 + intMarkCount], 2);
                AddHeaderCell(row1, "Khóa học", arrWidths[3 + intMarkCount + 1], 2);
                AddHeaderCell(row1, "Ghi chú", arrWidths[3 + intMarkCount + 2], 2);

                table.Rows.Add(row1);
                table.Rows.Add(row2);
            }

            table.EndInit();
            return table;
        }

        private static void AddHeaderCell(XRTableRow row, string strText, float fltWidth)
        {
            AddHeaderCell(row, strText, fltWidth, 1, 1);
        }

        private static void AddHeaderCell(XRTableRow row, string strText, float fltWidth, int intRowSpan)
        {
            AddHeaderCell(row, strText, fltWidth, intRowSpan, 1);
        }

        private static void AddHeaderCell(XRTableRow row, string strText, float fltWidth, int intRowSpan, int intColSpan)
        {
            XRTableCell cell = new XRTableCell();
            cell.Text = strText == null ? "" : strText;
            cell.WidthF = fltWidth;
            cell.BackColor = Color.FromArgb(204, 204, 204);
            cell.Borders = BorderSide.All;
            cell.TextAlignment = TextAlignment.MiddleCenter;
            cell.Font = new Font("Times New Roman", 9f, FontStyle.Bold);
            cell.Multiline = true;
            cell.CanGrow = true;
            if (intRowSpan > 1)
                cell.RowSpan = intRowSpan;
            // ColSpan trên XRTableCell DevExpress 11.1: dùng Weight/Width tổng; đã cộng width sẵn
            row.Cells.Add(cell);
        }

        private static XRTable BuildDetailTable(float[] arrWidths, int intMarkCount)
        {
            XRTable table = new XRTable();
            table.BeginInit();
            table.Font = new Font("Times New Roman", 9f);
            table.Borders = BorderSide.All;

            XRTableRow row = new XRTableRow();
            row.HeightF = 20f;

            AddBoundCell(row, "STT", arrWidths[0], TextAlignment.MiddleCenter);
            AddBoundCell(row, "FullName", arrWidths[1], TextAlignment.MiddleLeft);
            AddBoundCell(row, "BirthDate", arrWidths[2], TextAlignment.MiddleCenter);

            for (int i = 0; i < intMarkCount; i++)
            {
                XRTableCell cell = AddBoundCell(row, "Mark" + (i + 1).ToString(), arrWidths[3 + i], TextAlignment.MiddleCenter);
                cell.Tag = "IsFailed" + (i + 1).ToString();
                cell.BeforePrint += new PrintEventHandler(MarkCell_BeforePrint);
            }

            AddBoundCell(row, "ResultText", arrWidths[3 + intMarkCount], TextAlignment.MiddleCenter);
            AddBoundCell(row, "CourseName", arrWidths[3 + intMarkCount + 1], TextAlignment.MiddleCenter);
            AddBoundCell(row, "Description", arrWidths[3 + intMarkCount + 2], TextAlignment.MiddleLeft);

            table.Rows.Add(row);
            table.EndInit();
            return table;
        }

        private static XRTableCell AddBoundCell(XRTableRow row, string strField, float fltWidth, TextAlignment align)
        {
            XRTableCell cell = new XRTableCell();
            cell.WidthF = fltWidth;
            cell.Borders = BorderSide.All;
            cell.TextAlignment = align;
            cell.Font = new Font("Times New Roman", 9f);
            cell.DataBindings.Add("Text", null, strField);
            cell.CanGrow = true;
            row.Cells.Add(cell);
            return cell;
        }

        private static void MarkCell_BeforePrint(object sender, PrintEventArgs e)
        {
            XRTableCell cell = sender as XRTableCell;
            if (cell == null || cell.Tag == null)
                return;

            string strFailField = cell.Tag.ToString();
            object objRow = GetCurrentRow(cell);
            if (objRow == null)
                return;

            DataRowView drv = objRow as DataRowView;
            if (drv == null)
                return;

            if (drv.Row.Table.Columns.Contains(strFailField)
                && drv[strFailField] != DBNull.Value
                && Convert.ToBoolean(drv[strFailField]))
            {
                cell.BackColor = Color.Yellow;
            }
            else
            {
                cell.BackColor = Color.Transparent;
            }
        }

        private static object GetCurrentRow(XRControl control)
        {
            try
            {
                if (control.Report != null && control.Report.GetCurrentRow() != null)
                    return control.Report.GetCurrentRow();
            }
            catch
            {
            }
            return null;
        }
    }
}

