private void mnuItemPrintDrivingSummary_Click(object sender, EventArgs e)
{
    PrintDrivingSummaryReport();
}

private void PrintDrivingSummaryReport()
{
    if (dtbData == null || dtbClassSubject == null || dtbClassSubject.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    int[] arrExportIndexes = DrivingSummaryGetExportSubjectIndexes();
    int[] arrDrivingIndexes = DrivingSummaryGetDrivingGroupIndexes();
    bool bolHasDrivingGroup = arrDrivingIndexes != null;
    int intDrivingGroupStart = -1;
    if (bolHasDrivingGroup)
        intDrivingGroupStart = arrExportIndexes.Length - DRIVING_PRACTICE_GROUP_CODES.Length;

    string[] arrSubjectHeaders = new string[arrExportIndexes.Length];
    for (int i = 0; i < arrExportIndexes.Length; i++)
        arrSubjectHeaders[i] = dtbClassSubject.Rows[arrExportIndexes[i]]["SubjectName"].ToString();

    DataTable dtbReport = BuildDrivingSummaryReportData(arrExportIndexes);
    string strClassName = uClass.ClassName == null ? "" : uClass.ClassName.ToString().Trim();
    string strCourseName = uClass.CourseName == null ? "" : uClass.CourseName.ToString().Trim();

    XtraReport report = rptTongKetLaiXe.Create(
        dtbReport,
        arrSubjectHeaders,
        bolHasDrivingGroup,
        intDrivingGroupStart,
        DRIVING_PRACTICE_SUB_HEADERS,
        strClassName,
        strCourseName);

    try
    {
        rptTongKetLaiXe.SaveReport(report);
    }
    catch
    {
    }

    // Dùng frmReportView như QC99/QC14 nếu file .repx đã lưu; fallback preview trực tiếp
    string strReport = rptTongKetLaiXe.REPORT_RELATIVE_PATH;
    try
    {
        SystemManager.Report.frmReportView frm = new SystemManager.Report.frmReportView(dtbReport, strReport, false);
        frm.SetParameter("pClass", strClassName);
        frm.SetParameter("pCourse", strCourseName);
        frm.Show();
    }
    catch
    {
        rptTongKetLaiXe.ShowPreview(report);
    }
}

private DataTable BuildDrivingSummaryReportData(int[] arrExportIndexes)
{
    DataTable dtbReport = new DataTable();
    dtbReport.Columns.Add("STT", typeof(int));
    dtbReport.Columns.Add("FullName", typeof(string));
    dtbReport.Columns.Add("BirthDate", typeof(string));

    for (int i = 0; i < arrExportIndexes.Length; i++)
    {
        dtbReport.Columns.Add("Mark" + (i + 1).ToString(), typeof(string));
        dtbReport.Columns.Add("IsFailed" + (i + 1).ToString(), typeof(bool));
    }

    dtbReport.Columns.Add("ResultText", typeof(string));
    dtbReport.Columns.Add("CourseName", typeof(string));
    dtbReport.Columns.Add("Description", typeof(string));

    string strCourseName = uClass.CourseName == null ? "" : uClass.CourseName.ToString().Trim();
    int intSTT = 0;

    for (int i = 0; i < gvData.RowCount; i++)
    {
        DataRow drw = gvData.GetDataRow(i);
        if (drw == null)
            continue;

        intSTT++;
        DataRow drwNew = dtbReport.NewRow();
        drwNew["STT"] = intSTT;
        drwNew["FullName"] = (drw["StudentFirstName"].ToString() + " " + drw["StudentLastName"].ToString()).Trim();
        drwNew["BirthDate"] = drw["BirthDateText"].ToString().Trim();

        for (int x = 0; x < arrExportIndexes.Length; x++)
        {
            int intSubjectIndex = arrExportIndexes[x] + 1;
            string strField = "FinalSummary_" + intSubjectIndex.ToString();
            object objValue = drw[strField];
            string strValue = ModuleMarkFormatValue(objValue);
            if (strValue == "&nbsp;")
                strValue = "";

            drwNew["Mark" + (x + 1).ToString()] = strValue;
            drwNew["IsFailed" + (x + 1).ToString()] = ModuleMarkIsFailed(objValue);
        }

        drwNew["ResultText"] = drw["ResultText"].ToString().Trim();
        drwNew["CourseName"] = strCourseName;
        drwNew["Description"] = drw["Description"].ToString().Trim();
        dtbReport.Rows.Add(drwNew);
    }

    return dtbReport;
}

