using System;
using System.Data;
using System.Drawing;
using System.Drawing.Printing;
using System.IO;
using DevExpress.XtraPrinting;
using DevExpress.XtraReports.UI;
using DevExpress.XtraReports.Parameters;

class GenTongKetLaiXeRepx
{
    const int MARK_COUNT = 12;

    static int Main(string[] args)
    {
        string outPath = args.Length > 0
            ? args[0]
            : @"g:\0.CMS-MAIN-ALL-12\25.07.26 cd21\Report\StudentManager\Learning\Leaning_TongKetLaiXe.repx";

        string dir = Path.GetDirectoryName(outPath);
        if (!Directory.Exists(dir))
            Directory.CreateDirectory(dir);

        DataTable dtb = CreateSchema();
        XtraReport report = BuildReport(dtb);
        report.SaveLayout(outPath);
        Console.WriteLine("OK: " + outPath);
        return 0;
    }

    static DataTable CreateSchema()
    {
        DataTable dtb = new DataTable("TongKetLaiXe");
        dtb.Columns.Add("STT", typeof(int));
        dtb.Columns.Add("FullName", typeof(string));
        dtb.Columns.Add("BirthDate", typeof(string));
        for (int i = 1; i <= MARK_COUNT; i++)
        {
            dtb.Columns.Add("Mark" + i.ToString(), typeof(string));
            dtb.Columns.Add("IsFailed" + i.ToString(), typeof(bool));
        }
        dtb.Columns.Add("ResultText", typeof(string));
        dtb.Columns.Add("CourseName", typeof(string));
        dtb.Columns.Add("Description", typeof(string));
        return dtb;
    }

    static XtraReport BuildReport(DataTable dtb)
    {
        XtraReport report = new XtraReport();
        report.PaperKind = PaperKind.A4;
        report.Landscape = true;
        report.Margins = new Margins(40, 40, 40, 40);
        report.DataSource = dtb;
        report.DataMember = "";

        AddParam(report, "pClass");
        AddParam(report, "pCourse");
        for (int i = 1; i <= MARK_COUNT; i++)
            AddParam(report, "pSubject" + i.ToString());

        float pageW = report.PageWidth - report.Margins.Left - report.Margins.Right;

        PageHeaderBand ph = new PageHeaderBand();
        ph.Name = "PageHeader";
        report.Bands.Add(ph);

        DetailBand detail = new DetailBand();
        detail.Name = "Detail";
        detail.HeightF = 22f;
        report.Bands.Add(detail);

        // Header text
        XRLabel lblLeft = NewLabel(0, 0, pageW / 2f, 45f, "BINH ĐOÀN 15\r\nTRƯỜNG CAO ĐẲNG NGHỀ SỐ 21", true);
        XRLabel lblRight = NewLabel(pageW / 2f, 0, pageW / 2f, 45f, "CỘNG HOÀ XÃ HỘI CHỦ NGHĨA VIỆT NAM\r\nĐộc lập - Tự do - Hạnh phúc", true);
        ph.Controls.Add(lblLeft);
        ph.Controls.Add(lblRight);

        XRLine lineL = new XRLine();
        lineL.LocationF = new PointF((pageW / 2f - 160f) / 2f, 48f);
        lineL.SizeF = new SizeF(160f, 2f);
        ph.Controls.Add(lineL);

        XRLine lineR = new XRLine();
        lineR.LocationF = new PointF(pageW / 2f + (pageW / 2f - 140f) / 2f, 48f);
        lineR.SizeF = new SizeF(140f, 2f);
        ph.Controls.Add(lineR);

        XRLabel lblTitle = NewLabel(0, 55f, pageW, 20f, "TỔNG HỢP KẾT QUẢ KỲ KIỂM TRA KẾT THÚC MÔN HỌC", true);
        ph.Controls.Add(lblTitle);

        XRLabel lblSub = NewLabel(0, 75f, pageW, 18f, "LỚP [Parameters.pClass], KHÓA [Parameters.pCourse]", true);
        lblSub.Name = "lblSubTitle";
        // Bind parameters (DevExpress expression style in Text often works after LoadLayout)
        try
        {
            lblSub.DataBindings.Add(new XRBinding("Text", null, "Parameters.pClass"));
        }
        catch
        {
        }
        // Keep readable static pattern; runtime code will set Text if needed
        lblSub.Text = "LỚP , KHÓA ";
        lblSub.Name = "lblClassCourse";
        ph.Controls.Add(lblSub);

        float[] widths = BuildWidths(pageW);
        float tableTop = 95f;

        XRTable tblH = BuildHeader(widths);
        tblH.LocationF = new PointF(0f, tableTop);
        tblH.WidthF = pageW;
        ph.Controls.Add(tblH);
        ph.HeightF = tableTop + tblH.HeightF + 2f;

        XRTable tblD = BuildDetail(widths);
        tblD.LocationF = new PointF(0f, 0f);
        tblD.WidthF = pageW;
        detail.Controls.Add(tblD);
        detail.HeightF = tblD.HeightF;

        return report;
    }

    static void AddParam(XtraReport report, string name)
    {
        Parameter p = new Parameter();
        p.Name = name;
        p.Type = typeof(string);
        p.Value = "";
        p.Visible = false;
        report.Parameters.Add(p);
    }

    static XRLabel NewLabel(float x, float y, float w, float h, string text, bool bold)
    {
        XRLabel lbl = new XRLabel();
        lbl.LocationF = new PointF(x, y);
        lbl.SizeF = new SizeF(w, h);
        lbl.Text = text;
        lbl.Multiline = true;
        lbl.TextAlignment = TextAlignment.TopCenter;
        lbl.Font = new Font("Times New Roman", bold ? 11f : 10f, bold ? FontStyle.Bold : FontStyle.Regular);
        return lbl;
    }

    static float[] BuildWidths(float pageW)
    {
        float[] arr = new float[3 + MARK_COUNT + 3];
        arr[0] = 35f;
        arr[1] = 130f;
        arr[2] = 65f;
        float fixedRight = 65f + 65f + 80f;
        float remain = pageW - (arr[0] + arr[1] + arr[2] + fixedRight);
        float mw = remain / MARK_COUNT;
        for (int i = 0; i < MARK_COUNT; i++)
            arr[3 + i] = mw;
        arr[3 + MARK_COUNT] = 65f;
        arr[3 + MARK_COUNT + 1] = 65f;
        arr[3 + MARK_COUNT + 2] = 80f;

        float sum = 0f;
        for (int i = 0; i < arr.Length; i++) sum += arr[i];
        float scale = pageW / sum;
        for (int i = 0; i < arr.Length; i++) arr[i] *= scale;
        return arr;
    }

    static XRTable BuildHeader(float[] w)
    {
        // Row1: STT/Ten/NgaySinh rowspan2, Subject1..9 rowspan2, TH lái xe colspan3, KetQua/Khoa/GhiChu rowspan2
        // Row2: Trong hình, Chữ chi, Đường trường  (Mark10,11,12) - wait MARK 12 with last 3 as driving
        // Subjects 1..(MARK_COUNT-3) individual, last 3 = driving group
        int driveStart = MARK_COUNT - 3;

        XRTable table = new XRTable();
        table.BeginInit();
        table.Borders = BorderSide.All;
        table.Font = new Font("Times New Roman", 8f, FontStyle.Bold);

        XRTableRow r1 = new XRTableRow();
        r1.HeightF = 22f;
        XRTableRow r2 = new XRTableRow();
        r2.HeightF = 22f;

        AddH(r1, "STT", w[0], 2);
        AddH(r1, "Họ và tên học sinh", w[1], 2);
        AddH(r1, "Ngày sinh", w[2], 2);

        for (int i = 0; i < driveStart; i++)
        {
            XRTableCell c = AddH(r1, "pSubject" + (i + 1).ToString(), w[3 + i], 2);
            c.Name = "cellSubject" + (i + 1).ToString();
        }

        float gw = w[3 + driveStart] + w[3 + driveStart + 1] + w[3 + driveStart + 2];
        AddH(r1, "TH lái xe", gw, 1);

        string[] subs = new string[] { "Trong hình", "Chữ chi", "Đường trường" };
        for (int k = 0; k < 3; k++)
        {
            XRTableCell c = AddH(r2, subs[k], w[3 + driveStart + k], 1);
            c.Name = "cellDriveSub" + (k + 1).ToString();
        }

        AddH(r1, "Kết quả", w[3 + MARK_COUNT], 2);
        AddH(r1, "Khóa học", w[3 + MARK_COUNT + 1], 2);
        AddH(r1, "Ghi chú", w[3 + MARK_COUNT + 2], 2);

        table.Rows.Add(r1);
        table.Rows.Add(r2);
        table.EndInit();
        return table;
    }

    static XRTableCell AddH(XRTableRow row, string text, float width, int rowSpan)
    {
        XRTableCell cell = new XRTableCell();
        cell.Text = text;
        cell.WidthF = width;
        cell.BackColor = Color.FromArgb(204, 204, 204);
        cell.Borders = BorderSide.All;
        cell.TextAlignment = TextAlignment.MiddleCenter;
        cell.Font = new Font("Times New Roman", 8f, FontStyle.Bold);
        cell.Multiline = true;
        if (rowSpan > 1) cell.RowSpan = rowSpan;
        row.Cells.Add(cell);
        return cell;
    }

    static XRTable BuildDetail(float[] w)
    {
        XRTable table = new XRTable();
        table.BeginInit();
        table.Borders = BorderSide.All;
        table.Font = new Font("Times New Roman", 8f);

        XRTableRow row = new XRTableRow();
        row.HeightF = 20f;

        AddB(row, "STT", w[0], TextAlignment.MiddleCenter);
        AddB(row, "FullName", w[1], TextAlignment.MiddleLeft);
        AddB(row, "BirthDate", w[2], TextAlignment.MiddleCenter);
        for (int i = 1; i <= MARK_COUNT; i++)
            AddB(row, "Mark" + i.ToString(), w[3 + i - 1], TextAlignment.MiddleCenter);
        AddB(row, "ResultText", w[3 + MARK_COUNT], TextAlignment.MiddleCenter);
        AddB(row, "CourseName", w[3 + MARK_COUNT + 1], TextAlignment.MiddleCenter);
        AddB(row, "Description", w[3 + MARK_COUNT + 2], TextAlignment.MiddleLeft);

        table.Rows.Add(row);
        table.EndInit();
        return table;
    }

    static void AddB(XRTableRow row, string field, float width, TextAlignment align)
    {
        XRTableCell cell = new XRTableCell();
        cell.WidthF = width;
        cell.Borders = BorderSide.All;
        cell.TextAlignment = align;
        cell.Font = new Font("Times New Roman", 8f);
        cell.DataBindings.Add("Text", null, field);
        cell.Name = "cell" + field;
        row.Cells.Add(cell);
    }
}

