using System;
using System.Data;
using System.IO;
using System.Windows.Forms;
using DevExpress.XtraReports.UI;

namespace StudentManager.Learning
{
    /// <summary>
    /// Báo cáo tổng kết lái xe - file mẫu:
    /// Report/StudentManager/Learning/Leaning_TongKetLaiXe.repx
    /// </summary>
    public class rptTongKetLaiXe
    {
        public const string REPORT_RELATIVE_PATH = "Report/StudentManager/Learning/Leaning_TongKetLaiXe.repx";
        public const int MARK_COUNT = 12;

        public static string GetReportFullPath()
        {
            return Path.Combine(Application.StartupPath, REPORT_RELATIVE_PATH.Replace('/', Path.DirectorySeparatorChar));
        }

        public static bool ReportFileExists()
        {
            return File.Exists(GetReportFullPath());
        }

        public static XtraReport LoadReport(DataTable dtbDetail)
        {
            string strPath = GetReportFullPath();
            if (!File.Exists(strPath))
                throw new FileNotFoundException("Không tìm thấy file báo cáo: " + strPath);

            XtraReport report = new XtraReport();
            report.LoadLayout(strPath);
            report.DataSource = dtbDetail;
            return report;
        }

        public static void ApplyHeader(
            XtraReport report,
            string strClassName,
            string strCourseName,
            string[] arrSubjectHeaders)
        {
            if (report == null)
                return;

            if (strClassName == null) strClassName = "";
            if (strCourseName == null) strCourseName = "";
            if (arrSubjectHeaders == null) arrSubjectHeaders = new string[0];

            SetParameter(report, "pClass", strClassName);
            SetParameter(report, "pCourse", strCourseName);

            XRLabel lblSub = report.FindControl("lblClassCourse", true) as XRLabel;
            if (lblSub != null)
                lblSub.Text = String.Format("LỚP {0}, KHÓA {1}", strClassName, strCourseName);

            for (int i = 0; i < MARK_COUNT; i++)
            {
                string strSubject = "";
                if (i < arrSubjectHeaders.Length && arrSubjectHeaders[i] != null)
                    strSubject = arrSubjectHeaders[i];

                SetParameter(report, "pSubject" + (i + 1).ToString(), strSubject);

                XRTableCell cell = report.FindControl("cellSubject" + (i + 1).ToString(), true) as XRTableCell;
                if (cell != null)
                    cell.Text = strSubject;
            }
        }

        public static void ShowPreview(XtraReport report)
        {
            ReportPrintTool tool = new ReportPrintTool(report);
            tool.ShowPreview();
        }

        private static void SetParameter(XtraReport report, string strName, object objValue)
        {
            try
            {
                if (report.Parameters[strName] != null)
                    report.Parameters[strName].Value = objValue == null ? "" : objValue;
            }
            catch
            {
            }
        }
    }
}

